def is_smooth_2_5(N):
    """Checks if N only has prime factors 2 and 5."""
    if N <= 0:
        return False
    while N % 2 == 0:
        N //= 2
    while N % 5 == 0:
        N //= 5
    return N == 1

solutions = []
# m = n + 1. We check m from 1 up to 500.
for m in range(1, 501):
    K_m = m*m + 1
    if is_smooth_2_5(K_m):
        # n = m - 1
        n = m - 1
        solutions.append(n)
        print(f"Found solution n={n} (m={m}): {K_m}")

print("\nAll solutions found up to m=500:")
print(solutions)

def check_smoothness(number, primes=[2, 5]):
    if number <= 0:
        return False
    for p in primes:
        while number % p == 0:
            number //= p
    return number == 1

def solve_q(M):
    if M <= 1: return None
    Q = (M - 1)**2 + 1
    if check_smoothness(Q):
        return Q
    return None

M_values = []
# Search up to M = 1000, checking both M = 2^a 5^b and M = 5^b 2^a
for M in range(2, 1001):
    is_smooth_M = False
    temp_M = M
    while temp_M > 1:
        if temp_M % 2 == 0 or temp_M % 5 == 0:
            temp_M //= 2 if temp_M % 2 == 0 else 5
        else:
            break

    if temp_M == 1:
        M_values.append(M)

solutions = {}
print("Checking M values for Q = (M-1)^2 + 1:")
for M in M_values:
    Q = solve_q(M)
    if Q:
        solutions[M] = Q

